<script setup lang="ts">
import { LogOut, Menu, Smartphone } from 'lucide-vue-next'
defineProps<{ mobileMode?: boolean; menuOpen?: boolean }>()
defineEmits<{ menu: []; toggleMobile: [] }>()
const auth = useAuthStore()
const initials = computed(() => (auth.user?.name || 'Administrador').trim().split(/\s+/).slice(0, 2).map(part => part[0]).join('').toUpperCase())
const roleLabel = computed(() => ({ SUPERADMIN: 'Superadministrador', ADMIN: 'Administrador', ANALYST: 'Analista' } as Record<string, string>)[auth.user?.role || ''] || 'Administración')
</script>
<template>
  <header class="admin-header" :class="{ 'compact-header': mobileMode }">
    <button class="menu" type="button" :aria-label="menuOpen ? 'Cerrar menú administrativo' : 'Abrir menú administrativo'" aria-controls="admin-navigation" :aria-expanded="!!menuOpen" @click="$emit('menu')"><Menu /></button>
    <div class="head-title"><b>Tu espacio de trabajo</b><span>Estaciones, cultivos y decisiones conectadas</span></div>
    <div class="header-actions">
      <button class="mobile-toggle" type="button" :aria-pressed="!!mobileMode" aria-label="Vista móvil" @click="$emit('toggleMobile')"><Smartphone /><span>Vista móvil<small>{{ mobileMode ? 'Activada' : 'Desactivada' }}</small></span><i class="toggle-track" aria-hidden="true"><i /></i></button>
      <div class="user"><span class="user-avatar" aria-hidden="true">{{ initials }}</span><div><b>{{ auth.user?.name || 'Administrador' }}</b><span>{{ roleLabel }}</span></div></div>
      <button class="logout" type="button" title="Cerrar sesión" aria-label="Cerrar sesión" @click="auth.logout"><LogOut /></button>
    </div>
  </header>
</template>
